const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const escapeHtml = (value = "") => String(value).replace(/[&<>'"]/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" }[char]));
const percentage = (value) => `${Math.round(value * 100)}%`;
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

function setRuntimeStatus(mode, detail) {
  state.runtime = { mode, detail };
  const status = $("#runtime-status");
  if (status) {
    status.className = `runtime-status ${mode}`;
    const label = mode === "backend" ? (state.legalBert?.ready ? "FastAPI + Legal-BERT ready" : "FastAPI · rules only") : mode === "fallback" ? "Browser fallback" : "Checking API…";
    $("span", status).textContent = label;
    status.title = detail;
  }
  const processingMode = $("#processing-mode");
  if (processingMode) {
    processingMode.textContent = mode === "backend"
      ? `FastAPI · ${API_BASE_URL}`
      : mode === "fallback"
        ? "Browser fallback active · results are labeled"
        : "Checking FastAPI backend…";
  }
}

async function requestApi(path, payload, timeoutMs = 8000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const isForm = payload instanceof FormData;
    const response = await fetch(`${API_BASE_URL}${path}`, {
      method: payload === undefined ? "GET" : "POST",
      headers: payload === undefined || isForm ? { Accept: "application/json" } : { Accept: "application/json", "Content-Type": "application/json" },
      body: payload === undefined ? undefined : isForm ? payload : JSON.stringify(payload),
      signal: controller.signal,
    });
    const data = await response.json().catch(() => null);
    if (!response.ok) {
      const error = new Error(data?.error?.message ?? `API request failed with status ${response.status}`);
      error.status = response.status;
      error.details = data?.error?.details;
      throw error;
    }
    return data;
  } finally {
    clearTimeout(timer);
  }
}

async function checkBackendHealth() {
  setRuntimeStatus("checking", `Checking ${API_BASE_URL}`);
  try {
    const health = await requestApi("/api/health", undefined, 2500);
    state.legalBert = health.legalBert ?? null;
    setRuntimeStatus("backend", `${health.service} · ${health.engineVersion} · ${health.legalBert?.detail ?? "Legal-BERT status unknown"}`);
    return true;
  } catch (error) {
    setRuntimeStatus("fallback", `FastAPI unavailable: ${error.message}`);
    return false;
  }
}

async function executeWithFallback(path, payload, fallback, operation, notifyFallback = true, timeoutMs = 8000) {
  if (state.runtime.mode === "fallback" && !notifyFallback) return fallback();
  try {
    const result = await requestApi(path, payload, timeoutMs);
    setRuntimeStatus("backend", `${operation} returned by FastAPI at ${API_BASE_URL}`);
    return result;
  } catch (error) {
    if (error.status >= 400 && error.status < 500) throw error;
    setRuntimeStatus("fallback", `${operation} used browser engine: ${error.message}`);
    if (notifyFallback) toast(`${operation} used the deterministic browser engine because the API was unavailable.`, "Browser fallback");
    return fallback();
  }
}

function toast(message, label = "Done") {
  const region = $("#toast-region");
  const item = document.createElement("div");
  item.className = "toast";
  item.innerHTML = `<b>${escapeHtml(label)}</b>${escapeHtml(message)}`;
  region.append(item);
  setTimeout(() => item.remove(), 3400);
}

function showView(id, updateHash = true) {
  const target = document.getElementById(id) ?? document.getElementById("overview");
  $$(".view").forEach((view) => view.classList.toggle("active", view === target));
  $$("[data-nav]").forEach((link) => link.classList.toggle("active", link.dataset.nav === target.id));
  $("#view-title").textContent = target.dataset.title ?? "Overview";
  document.title = `${target.dataset.title ?? "Overview"} · RegulaTrace`;
  $(".sidebar").classList.remove("open");
  if (updateHash && location.hash !== `#${target.id}`) history.replaceState(null, "", `#${target.id}`);
  window.scrollTo({ top: 0, behavior: "smooth" });
  if (target.id === "evidence-graph") requestAnimationFrame(renderGraph);
}

function bindNavigation() {
  $$('[data-nav]').forEach((link) => link.addEventListener("click", (event) => {
    event.preventDefault();
    showView(link.dataset.nav);
  }));
  $$('[data-jump]').forEach((button) => button.addEventListener("click", () => showView(button.dataset.jump)));
  $("#mobile-menu").addEventListener("click", () => $(".sidebar").classList.toggle("open"));
  window.addEventListener("hashchange", () => showView(location.hash.slice(1) || "overview", false));
}

async function loadSample(name, notifyFallback = true) {
  state.sample = name;
  const sample = SAMPLES[name];
  state.sourceMetadata = { ...sample.meta };
  $("#source-title").value = sample.title;
  $("#regulation-input").value = sample.text;
  updateCharacterCount();
  state.analysis = await executeWithFallback(
    "/api/analyze",
    { text: sample.text, sourceMetadata: sample.meta, persist: false },
    () => analyzeDocument(sample.text, sample.meta),
    "Analysis",
    notifyFallback,
  );
  state.selectedRecord = state.analysis.normative[0] ?? state.analysis.records[0];
  renderAnalysis();
  renderGraph();
}

function updateCharacterCount() {
  const value = $("#regulation-input").value;
  $("#source-count").textContent = `${value.length.toLocaleString()} characters · ${value.trim().split(/\s+/).filter(Boolean).length} words`;
}

async function ingestDocument(file) {
  if (!file) return;
  const zone = $("#upload-zone");
  zone.classList.add("dragging");
  try {
    if (state.runtime.mode !== "backend") throw new Error("Start the FastAPI Presentation Edition to ingest PDF and DOCX files.");
    const form = new FormData();
    form.append("file", file);
    const result = await requestApi("/api/documents/ingest", form, 20000);
    state.sample = "upload";
    state.sourceMetadata = {
      authority: "Uploaded source",
      jurisdiction: "Unspecified",
      sourceId: `upload://${result.filename}`,
      version: new Date().toISOString().slice(0, 10),
      section: "Uploaded document",
    };
    $("#source-title").value = result.filename;
    $("#regulation-input").value = result.text;
    updateCharacterCount();
    toast(`${result.format} extracted: ${result.pages} page(s), ${result.words.toLocaleString()} words.`, "Document ready");
  } catch (error) {
    toast(error.message, "Ingestion failed");
  } finally {
    zone.classList.remove("dragging");
    $("#document-upload").value = "";
  }
}

function renderHistory() {
  const container = $("#history-list");
  if (!container) return;
  if (!state.history.length) {
    container.innerHTML = `<div class="empty-history">Run an analysis with FastAPI connected to create a persistent, reviewable case.</div>`;
    return;
  }
  container.innerHTML = state.history.map((item) => `<article class="history-row">
    <div><h3>${escapeHtml(item.sourceTitle)}</h3><p>${escapeHtml(item.analysisId)} · ${escapeHtml(item.authority)} · ${new Date(item.createdAt).toLocaleString()}</p></div>
    <div class="history-stat"><span>records</span><b>${item.recordCount}</b></div>
    <div class="history-stat"><span>reviewed</span><b>${item.reviewedCount}</b></div>
    <div class="history-stat"><span>unresolved</span><b>${item.unresolvedCount}</b></div>
    <button class="secondary-button small" data-load-analysis="${item.analysisId}">Open</button>
  </article>`).join("");
  $$('[data-load-analysis]', container).forEach((button) => button.addEventListener("click", async () => {
    try {
      state.analysis = await requestApi(`/api/analyses/${button.dataset.loadAnalysis}`);
      state.selectedRecord = state.analysis.normative[0] ?? state.analysis.records[0];
      renderAnalysis();
      renderGraph();
      showView("obligation-lab");
      toast(`Loaded ${state.analysis.analysisId}.`, "Case restored");
    } catch (error) { toast(error.message, "Load failed"); }
  }));
}

async function refreshHistory() {
  if (state.runtime.mode !== "backend") { state.history = []; renderHistory(); return; }
  try { state.history = await requestApi("/api/analyses?limit=8"); renderHistory(); } catch { state.history = []; renderHistory(); }
}

async function refreshDashboard() {
  if (state.runtime.mode !== "backend") return;
  try {
    state.dashboard = await requestApi("/api/dashboard");
    $("#kpi-analyses").textContent = state.dashboard.analyses.toLocaleString();
    $("#kpi-records").textContent = state.dashboard.records.toLocaleString();
    $("#kpi-reviewed").textContent = state.dashboard.reviewed.toLocaleString();
  } catch { /* Executive KPIs remain safely neutral while the API reconnects. */ }
}

async function runAnalysis() {
  const text = $("#regulation-input").value.trim();
  if (!text) return toast("Paste a regulatory clause before running the pipeline.", "Input needed");
  const button = $("#analyze-button");
  const progress = $("#pipeline-progress");
  const bar = $(".progress-track span", progress);
  button.disabled = true;
  progress.classList.add("running");
  try {
    for (const width of [18, 42, 72, 100]) {
      bar.style.width = `${width}%`;
      await sleep(120);
    }
    const sourceMetadata = { ...state.sourceMetadata, title: $("#source-title").value };
    state.analysis = await executeWithFallback(
      "/api/analyze",
      { text, sourceMetadata, persist: true },
      () => analyzeDocument(text, sourceMetadata),
      "Analysis",
    );
    state.selectedRecord = state.analysis.normative[0] ?? state.analysis.records[0];
    renderAnalysis();
    renderGraph();
    await refreshHistory();
    await refreshDashboard();
    toast(`${state.analysis.summary.obligationCount} obligations compiled with source evidence.`, "Pipeline complete");
  } catch (error) {
    toast(error.message, "Analysis failed");
  } finally {
    progress.classList.remove("running");
    bar.style.width = "0";
    button.disabled = false;
  }
}

function renderAnalysis() {
  const container = $("#obligation-list");
  const summary = $("#analysis-summary");
  if (!state.analysis) {
    summary.innerHTML = "";
    container.innerHTML = `<div class="empty-state"><div><span>⌁</span><b>No analysis yet</b><p>Load a sample or paste regulatory text to begin.</p></div></div>`;
    return;
  }
  const data = state.analysis.summary;
  summary.innerHTML = [
    [data.obligationCount, "obligations"],
    [data.clauseCount, "source clauses"],
    [percentage(data.avgConfidence), "mean confidence"],
    [percentage(data.citationIntegrity), "citation integrity"],
  ].map(([value, label]) => `<div class="summary-stat"><b>${escapeHtml(value)}</b><span>${label}</span></div>`).join("");

  container.innerHTML = state.analysis.records.map((record) => `
    <article class="obligation-item ${state.selectedRecord?.id === record.id ? "selected" : ""}" data-record-id="${record.id}" tabindex="0">
      <div class="obligation-top"><span class="obligation-id">${record.id}</span><span class="modality ${record.modality}">${record.modality}</span></div>
      <h3>${escapeHtml(record.actor)} → ${escapeHtml(record.action)}</h3>
      <p>${escapeHtml(record.evidence.slice(0, 165))}${record.evidence.length > 165 ? "…" : ""}</p>
      <div class="obligation-footer"><span>${escapeHtml(record.deadline ?? "No explicit deadline")}</span><span class="confidence">${percentage(record.confidence)} confidence</span></div>
    </article>`).join("");

  $$(".obligation-item", container).forEach((item) => {
    const select = () => {
      state.selectedRecord = state.analysis.records.find((record) => record.id === item.dataset.recordId);
      renderAnalysis();
      renderDetail();
      renderGraph();
    };
    item.addEventListener("click", select);
    item.addEventListener("keydown", (event) => { if (event.key === "Enter" || event.key === " ") select(); });
  });
  renderDetail();
}

function renderDetail() {
  const drawer = $("#detail-drawer");
  const record = state.selectedRecord;
  if (!record) { drawer.classList.remove("open"); return; }
  drawer.classList.add("open");
  const fields = [
    ["Actor", record.actor], ["Action", record.action], ["Deadline", record.deadline ?? "Not located"], ["Trigger / condition", record.condition ?? "Not located"],
    ["Exception", record.exception ?? "Not located"], ["Authority", record.authority], ["Version", record.sourceVersion], ["Review state", record.reviewState],
  ];
  drawer.innerHTML = `<div class="panel-head"><div><span class="panel-step">SELECTED RECORD</span><h2>${record.id}</h2></div><span class="modality ${record.modality}">${record.modality}</span></div>
    <div class="drawer-grid">${fields.map(([label, value]) => `<div class="drawer-field"><span>${label}</span><b>${escapeHtml(value)}</b></div>`).join("")}</div>
    <blockquote class="evidence-quote">“${escapeHtml(record.evidence)}”</blockquote>
    <div class="drawer-actions"><button class="primary-button small" data-review="CONFIRMED">Confirm record</button><button class="secondary-button small" data-review="CORRECTED">Mark corrected</button><button class="secondary-button small" data-review="REJECTED">Reject</button><button class="text-button" id="open-record-graph">Trace in graph →</button></div>`;
  $$('[data-review]', drawer).forEach((button) => button.addEventListener("click", async () => {
    const decision = button.dataset.review;
    button.disabled = true;
    try {
      if (state.analysis.analysisId && state.runtime.mode === "backend") {
        await requestApi("/api/reviews", { analysisId: state.analysis.analysisId, recordId: record.id, decision, reviewer: "Presentation reviewer" });
        await refreshHistory();
        await refreshDashboard();
      }
      record.reviewState = decision;
      state.analysis.normative.filter((item) => item.id === record.id).forEach((item) => { item.reviewState = decision; });
      renderDetail();
      renderGraph();
      toast(state.analysis.analysisId ? `Decision persisted for ${record.id}.` : "Decision retained in this browser session; run a saved backend analysis for persistence.", "Review saved");
    } catch (error) {
      button.disabled = false;
      toast(error.message, "Review failed");
    }
  }));
  $("#open-record-graph")?.addEventListener("click", () => showView("evidence-graph"));
}

function renderComparison() {
  const output = $("#comparison-output");
  if (!state.comparison) { output.innerHTML = ""; return; }
  const result = state.comparison;
  const outcomeText = result.outcome.replaceAll("_", " ");
  output.innerHTML = `<div class="comparison-result">
    <div class="score-panel"><div class="score-ring" style="--score:${Math.round(result.score * 100)}"><b>${Math.round(result.score * 100)}<span>/100</span></b></div><span class="outcome">${outcomeText}</span><p>Overall score cannot override a critical polarity or timing failure.</p></div>
    <div class="dimension-list">${result.dimensions.map((dimension) => `<article class="dimension-row"><header><span>${dimension.label}</span><b>${percentage(dimension.score)}</b></header><div class="dimension-track"><i style="width:${percentage(dimension.score)}"></i></div><p>${escapeHtml(dimension.detail)}</p></article>`).join("")}</div>
  </div>${renderModelSignal(result.modelSignal, "Action similarity")}${result.retrieval ? `<div class="retrieval-note"><b>Policy evidence selected from ${result.retrieval.candidateCount} clause${result.retrieval.candidateCount === 1 ? "" : "s"}</b><span>${escapeHtml(result.retrieval.selectedClause)}</span><small>Legal-BERT and lexical overlap ranked ${result.retrieval.consideredCount} candidate${result.retrieval.consideredCount === 1 ? "" : "s"}; explicit constraints determine the verdict.</small></div>` : ""}`;
}

function renderModelSignal(signal, scoreLabel = "Semantic similarity") {
  if (!signal) return `<div class="model-signal inactive"><b>Deterministic browser engine</b><span>Legal-BERT was not used for this result.</span></div>`;
  const active = signal.state === "active";
  const score = signal.cosineSimilarity == null ? "" : `<strong>${scoreLabel}: ${Math.round(signal.cosineSimilarity * 100)}% cosine</strong>`;
  return `<div class="model-signal ${active ? "active" : "inactive"}"><b>${active ? "LEGAL-BERT ACTIVE" : "RULE BASELINE"}</b><span>${escapeHtml(signal.detail)}</span>${score}<small>${active ? "Raw embedding similarity is not a probability or a compliance verdict." : "No neural model contributed to this result."}</small></div>`;
}

async function runComparison(notify = true) {
  const regulatoryText = $("#requirement-input").value.trim();
  const policyText = $("#policy-input").value.trim();
  if (!regulatoryText || !policyText) return toast("Provide both regulatory and policy text before comparing.", "Input needed");
  const button = $("#compare-button");
  button.disabled = true;
  try {
    state.comparison = await executeWithFallback(
      "/api/compare",
      { regulatoryText, policyText },
      () => comparePolicy(regulatoryText, policyText),
      "Policy comparison",
      notify,
      60000,
    );
    renderComparison();
    if (notify) toast(`Outcome: ${state.comparison.outcome.replaceAll("_", " ").toLowerCase()}.`, "Comparison complete");
  } catch (error) {
    toast(error.message, "Comparison failed");
  } finally {
    button.disabled = false;
  }
}

function renderChanges() {
  const output = $("#change-output");
  if (!state.changes) { output.innerHTML = ""; return; }
  const result = state.changes;
  output.innerHTML = `<div class="change-summary">
    <article class="impact-card primary"><span>Materiality score</span><b>${result.materialityScore}<small>/100</small></b><small>triage signal, not legal impact</small></article>
    <article class="impact-card"><span>Material changes</span><b>${result.changes.length}</b><small>${result.counts.MODIFIED ?? 0} modified clauses</small></article>
    <article class="impact-card"><span>Critical changes</span><b>${result.criticalCount}</b><small>review before effective date</small></article>
    <article class="impact-card"><span>Existing clauses affected</span><b>${result.affectedObligations}</b><small>modified or removed clauses</small></article>
  </div>
  ${renderModelSignal(result.modelSignal, "Clause similarity")}
  <p class="change-interpretation">Possible reasons are inferred from the wording. Confirm the regulator's intent with official explanatory material.</p>
  <div class="change-list">${result.changes.length ? result.changes.map((change) => `<article class="change-item"><span class="change-kind ${change.type}">${change.type}</span><div class="change-text">${change.before ? `<del>− ${escapeHtml(change.before)}</del>` : ""}${change.after ? `<ins>+ ${escapeHtml(change.after)}</ins>` : ""}${change.semanticSimilarity != null ? `<p class="alignment-note">${change.alignmentMethod === "legal-bert" ? "LEGAL-BERT ALIGNMENT" : "LEXICAL ALIGNMENT"} · Legal-BERT cosine ${Math.round(change.semanticSimilarity * 100)}%</p>` : ""}${change.explanation ? `<div class="change-explanation"><div class="change-explanation-head"><b>Why this may have changed</b><span class="rationale-status ${change.explanation.status}">${change.explanation.status === "INFERRED_FROM_TEXT" ? "TEXTUAL INFERENCE" : "REASON UNKNOWN"}</span></div><dl><div><dt>Observed</dt><dd>${escapeHtml(change.explanation.observed)}</dd></div><div><dt>Possible rationale</dt><dd>${escapeHtml(change.explanation.possibleRationale)}</dd></div><div><dt>Action to review</dt><dd>${escapeHtml(change.explanation.operationalImpact)}</dd></div></dl></div>` : ""}</div><span class="severity ${change.severity}">${change.severity}</span></article>`).join("") : `<p class="change-empty">No changed clauses were detected between these versions.</p>`}</div>`;
}

async function runDiff(notify = true) {
  const oldText = $("#old-version").value.trim();
  const newText = $("#new-version").value.trim();
  if (!oldText || !newText) return toast("Provide both versions before running Change Radar.", "Input needed");
  const button = $("#diff-button");
  button.disabled = true;
  try {
    state.changes = await executeWithFallback(
      "/api/versions/compare",
      { oldText, newText },
      () => compareVersions(oldText, newText),
      "Version comparison",
      notify,
      60000,
    );
    renderChanges();
    if (notify) toast(`${state.changes.changes.length} material changes routed for review.`, "Radar complete");
  } catch (error) {
    toast(error.message, "Change analysis failed");
  } finally {
    button.disabled = false;
  }
}

function nodePosition(id, index) {
  const fixed = {
    source: [115, 270], obligation: [385, 270], actor: [665, 110], action: [665, 225], deadline: [665, 340], exception: [665, 455], review: [900, 270],
  };
  return fixed[id] ?? [650, 100 + index * 95];
}

function svgTextLines(label, max = 24) {
  const words = String(label).split(/\s+/);
  const lines = [];
  let line = "";
  words.forEach((word) => {
    const candidate = `${line} ${word}`.trim();
    if (candidate.length > max && line) { lines.push(line); line = word; } else line = candidate;
  });
  if (line) lines.push(line);
  return lines.slice(0, 3);
}

function renderGraph() {
  const svg = $("#graph-svg");
  if (!svg) return;
  const record = state.selectedRecord ?? state.analysis?.normative?.[0];
  const graph = evidenceGraph(record);
  if (!record) { svg.innerHTML = ""; return; }
  const positions = Object.fromEntries(graph.nodes.map((node, index) => [node.id, nodePosition(node.id, index)]));
  const edges = graph.edges.map((edge) => {
    const [x1, y1] = positions[edge.from];
    const [x2, y2] = positions[edge.to];
    const midX = (x1 + x2) / 2;
    const midY = (y1 + y2) / 2 - 7;
    return `<g><line class="graph-edge" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" marker-end="url(#arrow)"/><text class="graph-edge-label" x="${midX}" y="${midY}" text-anchor="middle">${edge.label}</text></g>`;
  }).join("");
  const nodes = graph.nodes.map((node, index) => {
    const [x, y] = positions[node.id];
    const width = node.id === "action" || node.id === "exception" ? 205 : 170;
    const lines = svgTextLines(node.label, node.id === "action" || node.id === "exception" ? 29 : 21);
    return `<g class="graph-node ${node.type} ${node.id === "obligation" ? "active" : ""}" data-node="${node.id}" transform="translate(${x - width / 2},${y - 38})" tabindex="0" role="button"><rect width="${width}" height="76"></rect><text class="node-type" x="14" y="18">${node.type.toUpperCase()}</text><text x="14" y="40">${lines.map((line, lineIndex) => `<tspan x="14" dy="${lineIndex ? 14 : 0}">${escapeHtml(line)}</tspan>`).join("")}</text></g>`;
  }).join("");
  svg.innerHTML = `<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L0,6 L8,3 z" fill="#9daeb9"/></marker></defs>${edges}${nodes}`;
  svg.style.transform = `scale(${state.graphScale})`;
  $$(".graph-node", svg).forEach((node) => node.addEventListener("click", () => renderInspector(node.dataset.node)));
  renderInspector("obligation");
}

function renderInspector(nodeId) {
  const record = state.selectedRecord;
  if (!record) return;
  const map = {
    source: ["Source clause", record.section, record.evidence],
    obligation: ["Atomic obligation", record.id, "The normalized rule retains its exact evidence and source version."],
    actor: ["Accountable actor", record.actor, "Actor span proposed from the source clause."],
    action: ["Required action", record.action, "Action and object proposed from the normative predicate."],
    deadline: ["Temporal constraint", record.deadline ?? "Not located", "A deadline is useful only when its trigger or anchor is preserved."],
    exception: ["Exception scope", record.exception ?? "Not located", "Exceptions constrain an obligation; they do not become standalone duties."],
    review: ["Human release gate", record.reviewState, "No automated output becomes a compliance conclusion without confirmation."],
  };
  const [type, title, copy] = map[nodeId] ?? map.obligation;
  const inspector = $("#graph-inspector");
  inspector.innerHTML = `<span class="inspector-eyebrow">${type.toUpperCase()}</span><h2>${escapeHtml(title)}</h2><p>${escapeHtml(copy)}</p>
    <div class="inspector-stack"><div class="inspector-field"><span>Source version</span><b>${escapeHtml(record.sourceVersion)}</b></div><div class="inspector-field"><span>Evidence anchor</span><b>${escapeHtml(record.sourceId)} · ${escapeHtml(record.section)}</b></div><div class="inspector-field"><span>Validation state</span><b>${record.unresolved.length ? `Review ${record.unresolved.join(", ")}` : "Schema complete"}</b></div><div class="inspector-field"><span>Transformation</span><b>${ENGINE_VERSION}</b></div></div>
    <div class="confidence-scale"><header><span>Field confidence</span><b>${percentage(record.confidence)}</b></header><div class="track"><i style="width:${percentage(record.confidence)}"></i></div></div>`;
  $$(".graph-node").forEach((node) => node.classList.toggle("active", node.dataset.node === nodeId));
}

function renderEvaluation() {
  $("#baseline-chart").innerHTML = baselineData.map((item) => `<div class="bar-row"><span>${item.label}</span><div class="bar-track"><i style="--value:${item.value}%"></i></div><b>${item.value}%</b></div>`).join("");
  $("#challenge-list").innerHTML = challenges.map(([name, behavior]) => `<div class="challenge-row"><span>${name}</span><i>${behavior}</i></div>`).join("");
  $("#roadmap").innerHTML = roadmap.map(([week, title, detail, color]) => `<article class="roadmap-phase" style="--accent:${color}"><span>WEEK ${week}</span><b>${title}</b><small>${detail}</small></article>`).join("");
}

function renderBenchmark() {
  if (!state.benchmark) return;
  const result = state.benchmark;
  const pass = Math.round(result.passRate * 100);
  const miss = Math.round(result.metrics.criticalMissRate * 100);
  const provenance = Math.round(result.metrics.provenanceIntegrity * 100);
  $("#metric-pass-rate").textContent = `${pass}%`;
  $("#metric-miss-rate").textContent = `${miss}%`;
  $("#metric-provenance").textContent = `${provenance}%`;
  $("#metric-cases").textContent = result.executedCases;
  $("#metric-pass-bar").style.setProperty("--value", `${pass}%`);
  $("#metric-miss-bar").style.setProperty("--value", `${miss}%`);
  $("#metric-provenance-bar").style.setProperty("--value", `${provenance}%`);
  $("#metric-cases-bar").style.setProperty("--value", "100%");
  $("#benchmark-status").textContent = `${result.passedCases}/${result.executedCases} passed`;
  $("#kpi-benchmark").textContent = `${pass}%`;
  const cases = [...result.suites.extraction, ...result.suites.comparison, ...result.suites.versioning];
  $("#challenge-list").innerHTML = cases.map((item) => `<div class="challenge-row ${item.passed ? "pass" : "fail"}"><span>${item.id} · ${escapeHtml(item.observed ?? `${item.observedChanges} changes`)}</span><i>${item.passed ? "PASS" : "REVIEW"}</i></div>`).join("");
}

async function runBenchmark(notify = true) {
  if (state.runtime.mode !== "backend") {
    if (notify) toast("The executable benchmark requires the FastAPI Presentation Edition.", "Backend required");
    return;
  }
  const button = $("#run-benchmark");
  button.disabled = true;
  button.textContent = "Executing challenge suite…";
  try {
    state.benchmark = await requestApi("/api/evaluate", undefined, 15000);
    renderBenchmark();
    if (notify) toast(`${state.benchmark.passedCases}/${state.benchmark.executedCases} transparent cases passed.`, "Benchmark complete");
  } catch (error) {
    if (notify) toast(error.message, "Benchmark failed");
  } finally {
    button.disabled = false;
    button.textContent = "Execute live benchmark";
  }
}

